fn main() {
    let x = 5;
    x = 6;
    println!("{x}");
}

fn main() {
    let x = 5;
    let x = x + 1;
    let x = x * 2;
    println!("{x}");
}

fn main() {
    let spaces = "   ";
    let spaces = spaces.len();
    println!("{spaces}");
}

fn main() {
    let x = 1;
    {
        let x = x * 100;
        println!("inner: {x}");
    }
    println!("outer: {x}");
}

fn main() {
    let v = vec![1, 2, 3];
    v.push(4);
    println!("{v:?}");
}

fn main() {
    let mut count = 0;
    for i in 0..3 {
        let count = count + i;
        println!("{count}");
    }
    println!("final: {count}");
}

